function renderTimeline(){
  if(activeAnimPreset==='group')computeLongLayers();else if(isOffsetPreset())computeOffsetLayers();else computeLayers();
  const max=Math.max(1000,...layers.map(l=>l.end))+500;
  const scale=460/max;
  $('#tlInfo').textContent=layers.length+' layer';
  let ruler='';
  for(let ms=0;ms<=max;ms+=500){const x=ms*scale;ruler+=`<div class="rulerLine ${ms%1000===0?'major':''}" style="left:${x}px"></div>`;if(ms%1000===0)ruler+=`<div class="rulerLabel" style="left:${x}px">${(ms/1000).toFixed(0)}s</div>`}
  $('#timeRuler').innerHTML=ruler;
  let grid='<div class="gridBg">';
  for(let ms=0;ms<=max;ms+=250)grid+=`<div class="gridLine ${ms%1000===0?'major':''}" style="left:${ms*scale}px"></div>`;
  grid+='</div>';
  $('#timelineInner').style.width=Math.max(520,max*scale+70)+'px';
  const keyDur=Math.round(Number($('#layerDuration').value)*1000);
  $('#timelineInner').innerHTML=grid+layers.map(l=>{
    let kfs;
    if(activeAnimPreset==='group'){
      kfs=[0,keyDur*.22,keyDur*.48,keyDur*.70,keyDur*.88,keyDur].map(k=>(l.kfStart||0)+k);
    }else if(isOffsetPreset()){
      kfs=[0,keyDur*.41,keyDur].map(k=>(l.kfStart||0)+k);
    }else{
      kfs=[0,keyDur*.5,keyDur].map(k=>l.start+k);
    }
    const markers=kfs.filter(t=>t<=l.end).map(t=>`<div class="kfMarker" style="left:${t*scale}px"></div>`).join('');
    return `<div class="tlRow"><div class="tlName">${esc(l.ch)}</div><div class="tlTrack"><div class="tlBar" style="left:${l.start*scale}px;width:${Math.max(8,l.duration*scale)}px"></div>${markers}</div><div class="tlTime">${(activeAnimPreset==='group'||isOffsetPreset())?'0ms':l.start+'ms'}</div></div>`
  }).join('')}
